const MAP_HEIGHT = 6144;
const MAP_WIDTH = 4734;

const PAGE_MAP_WIDTH = 800;
const PAGE_MAP_HEIGHT = 1039;

const getXpercentOfMap = (x: number) => {
  return (x / MAP_WIDTH) * 100;
};

const getYpercentOfMap = (y: number) => {
  return (y / MAP_HEIGHT) * 100;
};

const getPageRegionXorWidth = (regionMapXorWidth: number) => {
  return (regionMapXorWidth / MAP_WIDTH) * PAGE_MAP_WIDTH;
};

const getPageRegionYorHeight = (regionMapYorHeight: number) => {
  return (regionMapYorHeight / MAP_HEIGHT) * PAGE_MAP_HEIGHT;
};

export class Region {
  id: number;
  title: string;
  color: string;
  lp: { x: number; y: number };
  rp: { x: number; y: number };

  constructor(
    id: number,
    title: string,
    color: string,
    lp: { x: number; y: number },
    rp: { x: number; y: number }
  ) {
    (this.color = color), (this.id = id);
    this.title = title;
    this.lp = lp;
    this.rp = rp;
  }

  get x() {
    return this.lp.x;
  }
  get y() {
    return this.lp.y;
  }
  get width() {
    return this.rp.x - this.lp.x;
  }
  get height() {
    return this.rp.y - this.lp.y;
  }
  get pageX() {
    return getPageRegionXorWidth(this.lp.x);
  }
  get pageY() {
    return getPageRegionYorHeight(this.lp.y);
  }
  get pageWidth() {
    return getPageRegionXorWidth(this.width);
  }
  get pageHeight() {
    return getPageRegionYorHeight(this.height);
  }
}

