import React from "react";

import {
  Button,
  Container,
  Flex,
  Group,
  Image,
  rem,
  Space,
  Text,
  Checkbox,
} from "@mantine/core";
import { useState, useEffect } from "react";
import { Rnd } from "react-rnd";

import Square from "./Square";

import zoneMap from "./zones-clear.jpg";
import { Region, STANDARD_REGIONS } from "./StandardRegions";

const getLocX = (x: number) => {
  return (x / 4734) * 100;
};
const getLocY = (y: number) => {
  return (y / 6144) * 100;
};

const standardZones = STANDARD_REGIONS.map((region: Region) => (
  <Rnd
    bounds="parent"
    enableResizing={false}
    disableDragging={true}
    default={{
      x: region.pageX,
      y: region.pageY,
      width: region.pageWidth,
      height: region.pageHeight,
    }}
    style={{
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      backgroundColor: region.color,
      color: "black",
    }}
  >
    {region.title}
  </Rnd>
));

const OutlandsMap = ({ soses }: { soses: Array<String> }) => {
  const [useStandard, setUseStandard] = useState(true);
  const [value, setValue] = useState({ x: 0.1, y: 0.1 });
  // const { ref, active } = useMove(setValue);
  const [zones, setZones] = useState(standardZones);

  useEffect(() => {
    if (useStandard) {
      setZones(standardZones);
    }
    else {
      setZones([]);
    }
  }, [useStandard]);

  return (
    <Container>
      <Container>
        <Group grow>
          <Text size="xl" inline>
            Regions
          </Text>
          <Flex
            gap="md"
            justify="flex-end"
            align="center"
            direction="row"
            wrap="wrap"
          >
            <Checkbox
              label="Standard regions"
              checked={useStandard}
              onChange={(event) => setUseStandard(event.currentTarget.checked)}
            />
            <Button
              onClick={(
                event: React.MouseEvent<HTMLButtonElement, MouseEvent>
              ) => {
                let newZone = <Square loc={value} />;
                setZones([...zones, newZone]);
                event.preventDefault();
              }}
              variant="filled"
              disabled={useStandard}
            >
              + Region
            </Button>
          </Flex>
        </Group>
        <Space h="md" />
      </Container>
      <div
        // ref={ref}
        style={{ width: rem(800), height: rem(1039), position: "relative" }}
      >
        <Image radius="md" src={zoneMap} />
        {zones}
        {soses.map((sos: String) => {
          const cords = sos.split(",");
          const location = [parseInt(cords[0]), parseInt(cords[1])];

          return (
            <div
              style={{
                position: "absolute",
                left: `calc(${getLocX(location[0])}% - ${rem(4)})`,
                top: `calc(${getLocY(location[1])}% - ${rem(4)})`,
                width: rem(4),
                height: rem(4),
                borderRadius: rem(16),
                backgroundColor: `rgba(255,0,0,1)`,
              }}
            />
          );
        })}
      </div>
    </Container>
  );
};

export default OutlandsMap;
